import warp as wpfrom . import collision_driverfrom . import smooth_accfrom . import smooth_actuatorfrom . import smooth_customfrom . import smooth_frcfrom . import smooth_hunt_crossleyfrom . import smooth_exp_contactsfrom . import smooth_exp_contacts_hcfrom . import smooth_inertfrom . import smooth_limitsfrom . import smooth_mobilizer_postfrom . import smooth_muscle_actfrom . import smooth_muscle_eqfrom . import smooth_muscle_fnfrom . import smooth_muscle_metabolicfrom . import smooth_muscle_postfrom . import smooth_muscle_ptfrom . import smooth_posfrom . import smooth_resetfrom . import smooth_velfrom .types import Datafrom .types import Modelfrom .warp_util import event_scopewp.set_module_options({"enable_backward": False})@event_scopedef reset_forces(m: Model, d: Data):    smooth_frc.reset_forces(m, d)@event_scopedef realize_position(m: Model, d: Data, run_reset: bool = False):    """ Position-dependent computations. """    # If we requested a reset, let's make sure we're within the joint limits    if run_reset:        smooth_reset.fix_qpos_limits(m, d)        smooth_reset.fix_quaternions(m, d)    # evaluate the functions for custom joints    smooth_custom.evaluate_cst_functions(m, d)    smooth_custom.prepare_cst_joint(m, d)    # mobilizer transforms    smooth_pos.calc_mobilizer_X_FM(m, d)    # body world positions    smooth_pos.calc_body_transforms(m, d)    # across-joint velocity Jacobian    smooth_pos.joint_velocity_jacobian(m, d)    # COM and inertia matrices    smooth_pos.joint_independent_kinematics(m, d)    # world positions for colliders, visuals, sites    smooth_pos.attachment_kinematics(m, d)    # COM of body trees    smooth_pos.com_pos(m, d)    # detect contacts    collision_driver.collision(m, d)    # finally, reset any contact state if requested    if run_reset:        # smooth_exp_contacts.reset_exp_contact_state(m, d)        smooth_exp_contacts_hc.reset_exp_contact_state(m, d)    return@event_scopedef realize_velocity(m: Model, d: Data):    """Velocity-dependent computations."""    # compute qdot = N(q) * u    smooth_vel.calc_q_dot(m, d)    # body velocities    smooth_vel.compute_body_velocities(m, d)    # derivative of the velocity Jacobian    smooth_vel.joint_velocity_jacobian_dot(m, d)    # body accelerations from parent to child body    smooth_vel.compute_parent_to_child_accelerations(m, d)    # gyroscopic moment, coriolis acceleration    smooth_vel.joint_independent_kinematics_vel(m, d)    # world velocities for sites    smooth_vel.attachment_kinematics_vel(m, d)    # compute muscle path: note we fuse the path length and velocity computations for performance    smooth_muscle_fn.muscle_fn_path(m, d)    smooth_muscle_pt.muscle_point_path(m, d)    return@event_scopedef realize_articulated_body(m: Model, d: Data):    smooth_inert.initialize_articulated_body_inertia(m, d)    smooth_inert.accumulate_articulated_body_inertia(m, d)    smooth_inert.articulated_body_velocity(m, d)    return@event_scopedef compute_accelerations(m: Model, d: Data):    smooth_acc.calc_udot(m, d)    return@event_scopedef realize_muscles(m: Model, d: Data, run_reset: bool):    """ Muscle-related computations. """    # Activation dynamics    smooth_muscle_act.activation_dynamics(m, d)    # Contraction dynamics, equilibrate if reset    if run_reset:        smooth_muscle_eq.equilibrate(m, d)    smooth_muscle_eq.contraction_dynamics(m, d)    return@event_scopedef realize_actuators(m: Model, d: Data, run_reset: bool):    """ Actuator-related computations. """    if run_reset:        smooth_actuator.reset_to_default_activation(m, d)    smooth_actuator.activation_dynamics(m, d)    return@event_scopedef realize_forces(m: Model, d: Data):    if m.opt.explicit_gravity:        smooth_frc.apply_gravity(m, d)    # spring, damping, drag    smooth_frc.spring(m, d)    smooth_frc.damping(m, d)    # contacts    smooth_hunt_crossley.contact_forces_hc(m, d)    # smooth_exp_contacts.contact_forces_exp(m, d)    smooth_exp_contacts_hc.contact_forces_exp(m, d)    # limits    smooth_limits.coordinate_limit_force(m, d)    smooth_limits.swing_twist_limit_force(m, d)    # muscles    smooth_muscle_fn.apply_muscle_force_fn(m, d)    smooth_muscle_pt.apply_muscle_force_pt(m, d)    # actuators    smooth_actuator.actuator_force(m, d)    # convert any qfrc into ufrc    smooth_frc.qfrc_to_ufrc(m, d)    # accumulate    smooth_frc.accumulate_forces(m, d)    return@event_scopedef fwd(m: Model, d: Data):    """ Forward dynamics (i.e., realize state). No integration """    reset_forces(m, d)    realize_position(m, d, run_reset=False)    realize_velocity(m, d)    realize_articulated_body(m, d)    realize_muscles(m, d, run_reset=False)    realize_actuators(m, d, run_reset=False)    realize_forces(m, d)    compute_accelerations(m, d)@event_scopedef reset(m: Model, d: Data):    """ Called after resetting any of the worlds. Enforces joint limits, equilibrates muscles, realize state """    reset_forces(m, d)    realize_position(m, d, run_reset=True)    realize_velocity(m, d)    realize_articulated_body(m, d)    realize_muscles(m, d, run_reset=True)    realize_actuators(m, d, run_reset=True)    realize_forces(m, d)    compute_accelerations(m, d)    d.world_reset.zero_()@event_scopedef fk(m: Model, d: Data):    """ Forward kinematics only for position-dependent quantities """    realize_position(m, d)@event_scopedef compute_muscle_moments(m: Model, d: Data):    """    Used for computing muscle moment arms (especially for point-based muscles). Applies muscle forces    """    # Point-path based muscles.    body_F_tmp = wp.zeros((d.nworld, m.nbody), dtype=wp.spatial_vector)    ufrc_tmp = wp.zeros((d.nworld, m.nv), dtype=float)    for muscle_id in range(wp.static(m.nmuscle)):        # Compute body F for a unit actuation,        smooth_muscle_pt.apply_unit_force_one_muscle(m, d, body_F_out=body_F_tmp, muscle_id=muscle_id)        # Then compute generalized force f = J^T F.        smooth_mobilizer_post.multiply_by_jacobian_transpose(m, d, X_in=body_F_tmp, JtX_out=ufrc_tmp)        # Store the result into muscle moment arm        smooth_muscle_post.copy_ufrc_into_moment_arm(m, d, muscle_id=muscle_id, ufrc=ufrc_tmp)        # Reset for next muscle        body_F_tmp.zero_()    return@event_scopedef compute_net_joint_moments(m: Model, d: Data):    """ Multiply acceleration by M to compute net joint moments """    smooth_mobilizer_post.multiply_by_mass(m, d, d.qacc, d.joint_moments)@event_scopedef post(m: Model, d: Data):    """ Post-processing computations. """    # TODO: checkme later if metabolics is needed    # smooth_muscle_metabolic.compute_muscle_metabolics(m, d)    return